module tb_TopModule;

    logic clk;
    logic reset;
    logic [3:0] q;

    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // Clock generation
    always #5 clk = ~clk;

    initial begin
        clk = 0;
        reset = 1;
        #12;
        if (q !== 4'd0) begin
            $display("SELFTEST FAIL: Reset failed, q = %0d", q);
            $finish;
        end

        reset = 0;

        // Check counting sequence 0 to 15 and wrap around
        for (int i = 0; i < 35; i++) begin
            #10;
            // Expected value should be (previous expected + 1) % 16, but wait:
            // At posedge clk, q updates. Let's trace carefully relative to clk edges.
        end

        // Let's write a cleaner testbench using posedge clk syncing.
    end

    // Better testbench structure:
    initial begin
        clk = 0;
        reset = 1;
        @(posedge clk);
        #1;
        if (q !== 4'd0) begin
            $display("SELFTEST FAIL: reset did not set q to 0");
            $finish;
        end

        reset = 0;
        for (int i = 0; i < 30; i++) begin
            @(posedge clk);
            #1; // small delay to sample after posedge
            if (q !== ((i + 1) % 16)) begin
                $display("SELFTEST FAIL: at step %0d, expected %0d, got %0d", i, (i + 1) % 16, q);
                $finish;
            end
        end

        // Test synchronous reset during operation
        @(posedge clk);
        reset = 1;
        #1;
        if (q !== 4'd0) begin
            $display("SELFTEST FAIL: synchronous reset during run failed");
            $finish;
        end

        @(posedge clk);
        reset = 0;
        #1;
        if (q !== 4'd1) begin
            $display("SELFTEST FAIL: post-reset count failed");
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end

endmodule
